#include <iostream>
#include <fstream>
#include <string>
#include <mutex>
#include <thread>
#include <chrono>
#include <cstring>
#include <sys/stat.h>
#include <unistd.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>

namespace serialization {

struct AuthToken {
    char service_id[64];
    uint64_t timestamp;
    uint32_t permissions;
    char hmac_signature[32];
};

class TokenSerializer {
private:
    std::mutex file_mutex_;
    std::string shared_secret_;
    std::string token_path_;

    bool verify_hmac(const AuthToken& token) {
        unsigned char computed[32];
        unsigned int len = 32;
        // HMAC over service_id + timestamp + permissions
        std::string data(token.service_id);
        data += std::to_string(token.timestamp);
        data += std::to_string(token.permissions);
        HMAC(EVP_sha256(), shared_secret_.c_str(), shared_secret_.size(),
             (unsigned char*)data.c_str(), data.size(), computed, &len);
        return memcmp(computed, token.hmac_signature, 32) == 0;
    }

    bool check_file_ownership(const std::string& path) {
        struct stat st;
        if (stat(path.c_str(), &st) != 0) return false;
        // File must be owned by root or the service user
        return (st.st_uid == 0 || st.st_uid == getuid());
    }

    bool check_file_permissions(const std::string& path) {
        struct stat st;
        if (stat(path.c_str(), &st) != 0) return false;
        // File must not be world-writable
        return (st.st_mode & S_IWOTH) == 0;
    }

public:
    TokenSerializer(const std::string& secret, const std::string& path)
        : shared_secret_(secret), token_path_(path) {}

    // Serialize token to shared file for cross-service auth
    bool serialize_token(const AuthToken& token) {
        std::lock_guard<std::mutex> lock(file_mutex_);
        std::ofstream ofs(token_path_, std::ios::binary);
        if (!ofs) return false;
        ofs.write(reinterpret_cast<const char*>(&token), sizeof(AuthToken));
        return ofs.good();
    }

    // Deserialize and validate token from cross-service file
    bool deserialize_and_validate(AuthToken& token_out) {
        std::lock_guard<std::mutex> lock(file_mutex_);

        // Security check 1: verify file ownership
        if (!check_file_ownership(token_path_)) {
            std::cerr << "Token file ownership check failed" << std::endl;
            return false;
        }

        // Security check 2: verify file permissions
        if (!check_file_permissions(token_path_)) {
            std::cerr << "Token file permissions check failed" << std::endl;
            return false;
        }

        // Security check 3: verify file hasn't been modified recently
        // (anti-tampering: file must be at least 100ms old)
        struct stat st;
        if (stat(token_path_.c_str(), &st) != 0) return false;
        auto file_mtime = st.st_mtim.tv_sec;
        auto now = time(nullptr);
        if (now - file_mtime > 300) {
            std::cerr << "Token file too old (>5min)" << std::endl;
            return false;
        }

        // All checks passed, now read the file
        std::ifstream ifs(token_path_, std::ios::binary);
        if (!ifs) return false;
        ifs.read(reinterpret_cast<char*>(&token_out), sizeof(AuthToken));
        if (!ifs.good()) return false;

        // Security check 4: verify HMAC signature
        if (!verify_hmac(token_out)) {
            std::cerr << "Token HMAC verification failed" << std::endl;
            memset(&token_out, 0, sizeof(AuthToken));
            return false;
        }

        // Security check 5: verify timestamp freshness
        uint64_t current_time = static_cast<uint64_t>(time(nullptr));
        if (current_time - token_out.timestamp > 60) {
            std::cerr << "Token expired" << std::endl;
            memset(&token_out, 0, sizeof(AuthToken));
            return false;
        }

        return true;
    }

    // Grant access based on deserialized token
    bool authorize_request(const std::string& requested_service,
                          uint32_t required_perms) {
        AuthToken token;
        if (!deserialize_and_validate(token)) {
            return false;
        }

        // Check if token grants required permissions
        if ((token.permissions & required_perms) != required_perms) {
            std::cerr << "Insufficient permissions" << std::endl;
            return false;
        }

        std::cout << "Access granted to service: "
                  << token.service_id << std::endl;
        return true;
    }
};

} // namespace serialization

int main() {
    serialization::TokenSerializer ts("super_secret_key_2024",
                                       "/tmp/auth_tokens/service.tok");

    // Example: authorize incoming request
    if (ts.authorize_request("data-pipeline", 0x03)) {
        std::cout << "Processing authorized request..." << std::endl;
    }
    return 0;
}
